const STORE='actuary-recall-progress-v1';
const SETTINGS='actuary-recall-settings-v1';
let cards=[];
let view='home';
let session=null;
const app=document.querySelector('#app');

const progress=()=>{try{return JSON.parse(localStorage.getItem(STORE))||{}}catch{return {}}};
const save=(value)=>localStorage.setItem(STORE,JSON.stringify(value));
const recordFor=(id)=>progress()[id]||{attempts:0,score:0,last:0,due:0};
const pointRecords=(card)=>recordFor(card.id).points||{};
const pointWeakness=(card)=>{const values=Object.values(pointRecords(card));return values.length?Math.min(...values.map(p=>p.score??0)):recordFor(card.id).score||0};
const mastery=(card)=>{const r=recordFor(card.id);return !r.attempts?'New':r.score<2?'Learning':r.score<4?'Developing':r.score<7?'Strong':'Mastered'};
const masteryPercent=(card)=>Math.min(100,Math.round((recordFor(card.id).score/7)*100));
const dueCards=()=>cards.filter(c=>recordFor(c.id).due<=Date.now()).sort((a,b)=>recordFor(a.id).score-recordFor(b.id).score);
const totalMastery=()=>Math.round(cards.reduce((n,c)=>n+masteryPercent(c),0)/(cards.length||1));
const escapeHtml=(s='')=>s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const shuffle=(items)=>items.map(v=>[Math.random(),v]).sort((a,b)=>a[0]-b[0]).map(([,v])=>v);
const settings=()=>{try{return JSON.parse(localStorage.getItem(SETTINGS))||{}}catch{return {}}};
const reviewUpdate=(old={},quality=3)=>{let ease=old.ease||2.5,streak=old.streak||0,interval=old.interval||0;if(quality<3){streak=0;interval=quality===0?0:1}else{streak++;interval=streak===1?1:streak===2?3:Math.max(4,Math.round(interval*ease));ease=Math.max(1.3,ease+.1-(5-quality)*(.08+(5-quality)*.02))}return {...old,ease,streak,interval,due:Date.now()+interval*86400000,last:Date.now()}};
function examPlan(){const date=settings().examDate;if(!date)return `<div class="exam-plan"><strong>Set an exam date</strong><span>Turn the remaining material into a daily target.</span><input id="examDate" type="date" aria-label="Exam date"></div>`;const days=Math.max(1,Math.ceil((new Date(date+'T12:00:00')-Date.now())/86400000)),remaining=cards.filter(c=>masteryPercent(c)<75).length,target=Math.max(1,Math.ceil(remaining/days));return `<div class="exam-plan"><strong>${days} days to the exam</strong><span>${remaining} acronyms need work · target ${target} per day</span><input id="examDate" type="date" value="${date}" aria-label="Exam date"></div>`}

function setView(next){view=next;session=null;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));render();app.focus();}

function home(){
  const due=dueCards().length;
  const mastered=cards.filter(c=>mastery(c)==='Mastered').length;
  return `<section class="hero"><p class="eyebrow">Today’s revision</p><h1>${due} acronyms<br>ready to recall.</h1><p>A focused session prioritising new and weaker material.</p><button class="primary" data-start="daily">Start daily session&nbsp; →</button></section>
  ${examPlan()}<div class="stat-grid"><div class="stat"><strong>${totalMastery()}%</strong><span>overall mastery</span></div><div class="stat"><strong>${mastered}</strong><span>mastered</span></div><div class="stat"><strong>${cards.length}</strong><span>total acronyms</span></div></div>
  <div class="section-head"><div><p class="eyebrow">Quick practice</p><h2>Choose your challenge</h2></div></div>
  <div class="mode-grid">${modeCard('recall','◎','Recall lists','Retrieve the acronym and every point.')}${modeCard('weakpoint','◉','Weak-point drill','Test the exact rows previously missed.')}${modeCard('write','✎','Write the whole list','Type the mnemonic and full answer.')}${modeCard('weak','⚑','Weakest first','Focus on material that needs attention.')}${modeCard('learn','◇','Learn mode','Reveal a new list one point at a time.')}${modeCard('sprint','ϟ','Exam sprint','Ten mixed, rapid-fire questions.')}</div>`;
}
function modeCard(mode,icon,title,copy){return `<button class="mode-card" data-start="${mode}"><span class="mode-icon">${icon}</span><strong>${title}</strong><span>${copy}</span></button>`}
function practice(){return `<p class="eyebrow">Practice</p><h1>Train the recall,<br>not recognition.</h1><p class="muted">Choose how you want to retrieve the material. Each result shapes what comes up next.</p><div class="mode-grid">${modeCard('daily','◷','Daily session','Your scheduled mix of new and due cards.')}${modeCard('recall','◎','Recall lists','Retrieve the mnemonic and complete list.')}${modeCard('weakpoint','◉','Weak-point drill','Test individual points that have caused trouble.')}${modeCard('write','✎','Write the whole list','Produce an exam-style answer before checking.')}${modeCard('weak','⚑','Weakest first','Target the lowest-confidence cards.')}${modeCard('learn','◇','Learn mode','Study lists progressively before testing.')}${modeCard('sprint','ϟ','Exam sprint','Ten mixed questions with no detours.')}</div>`}

function library(){const cats=['All',...new Set(cards.map(c=>c.category))];return `<p class="eyebrow">Library</p><h1>All ${cards.length}<br>acronyms.</h1><input class="search" id="search" type="search" placeholder="Search acronym or topic…" aria-label="Search acronym library"><div class="filters">${cats.map((c,i)=>`<button class="filter ${i?'':'active'}" data-category="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('')}</div><div id="libraryList" class="library-list">${libraryRows(cards)}</div>`}
function libraryRows(list){return list.length?list.map(c=>`<button class="library-card" data-card="${c.id}"><span><strong>${escapeHtml(c.acronym)}</strong><small>${escapeHtml(c.topic)}</small>${c.review?'<small class="notice">Source wording needs review</small>':''}</span><span class="mastery">${mastery(c)} · ${masteryPercent(c)}%</span></button>`).join(''):'<div class="empty">No acronyms match that search.</div>'}

function progressView(){const attempted=cards.filter(c=>recordFor(c.id).attempts);const weakest=[...cards].sort((a,b)=>pointWeakness(a)-pointWeakness(b)).slice(0,5);const weakPoints=cards.flatMap(c=>c.points.map((p,i)=>({card:c,point:p,record:pointRecords(c)[i]}))).filter(x=>x.record?.reveals).sort((a,b)=>(b.record.reveals-a.record.reveals)||(a.record.score-b.record.score)).slice(0,6);const cats=[...new Set(cards.map(c=>c.category))];return `<p class="eyebrow">Progress</p><h1>${totalMastery()}% overall<br>mastery.</h1><p class="muted">Based on recall quality and repeated successful reviews.</p><div class="stat-grid"><div class="stat"><strong>${attempted.length}</strong><span>studied</span></div><div class="stat"><strong>${cards.filter(c=>mastery(c)==='Strong'||mastery(c)==='Mastered').length}</strong><span>strong</span></div><div class="stat"><strong>${cards.reduce((n,c)=>n+recordFor(c.id).attempts,0)}</strong><span>attempts</span></div></div><div class="section-head"><h2>By topic</h2></div>${cats.map(cat=>{const set=cards.filter(c=>c.category===cat);const pct=Math.round(set.reduce((n,c)=>n+masteryPercent(c),0)/set.length);return `<div class="progress-row"><header><strong>${escapeHtml(cat)}</strong><small>${pct}%</small></header><div class="bar"><i style="width:${pct}%"></i></div></div>`}).join('')}${weakPoints.length?`<div class="section-head"><h2>Weak recall points</h2></div>${weakPoints.map(x=>`<button class="library-card wide" data-card="${x.card.id}"><span><strong>${escapeHtml(x.card.acronym)} · ${x.point.letter}</strong><small>${escapeHtml(x.point.text)}</small></span><span class="mastery">Revealed ${x.record.reveals}×</span></button>`).join('')}`:''}<div class="section-head"><h2>Needs attention</h2></div>${weakest.map(c=>`<button class="library-card wide" data-card="${c.id}"><span><strong>${escapeHtml(c.acronym)}</strong><small>${escapeHtml(c.topic)}</small></span><span class="mastery">${mastery(c)}</span></button>`).join('')}`}

function start(mode,onlyCard){
  if(mode==='weakpoint'){const points=cards.flatMap(card=>card.points.map((point,index)=>({card,point,index,record:pointRecords(card)[index]}))).sort((a,b)=>((b.record?.reveals||0)-(a.record?.reveals||0))||((a.record?.score||0)-(b.record?.score||0)));session={mode,cards:(points.some(x=>x.record)?points.filter(x=>x.record).slice(0,10):shuffle(points).slice(0,10)),index:0,revealed:false,results:[]};return renderStudy()}
  let pool=onlyCard?[onlyCard]:mode==='weak'?[...cards].sort((a,b)=>pointWeakness(a)-pointWeakness(b)).slice(0,10):mode==='daily'?dueCards().slice(0,10):shuffle(cards).slice(0,mode==='sprint'?10:10);
  if(!pool.length)pool=shuffle(cards).slice(0,10);
  session={mode:mode==='daily'?'recall':mode,cards:pool,index:0,revealed:false,acronymRevealed:false,revealedPoints:new Set(),pointCount:mode==='learn'?1:0,results:[]};renderStudy();
}
function renderStudy(){
  if(session.index>=session.cards.length)return renderSummary();
  if(session.mode==='weakpoint')return renderWeakPoint();
  if(session.mode==='write')return renderWrite();
  const c=session.cards[session.index], testing=session.mode!=='learn';
  const rows=c.points.map((p,i)=>{const pointShown=session.revealed||session.mode==='learn'&&i<session.pointCount||session.revealedPoints.has(i);return `<div class="point ${pointShown?'':'concealed'}" data-point="${i}" role="button" tabindex="0" aria-label="${pointShown?'Answer revealed':'Reveal answer for this row'}">${pointShown?`<span class="letter">${p.letter}</span>`:''}<span class="point-text">${escapeHtml(p.text)}</span>${pointShown&&testing?`<span class="row-ratings"><button data-row-score="0" data-index="${i}">Missed</button><button data-row-score="1" data-index="${i}">Nearly</button><button data-row-score="2" data-index="${i}">Knew it</button></span>`:''}</div>`}).join('');
  app.innerHTML=`<div class="study-head"><button class="back" data-exit aria-label="Leave session">←</button><div class="study-progress"><i style="width:${(session.index/session.cards.length)*100}%"></i></div><span class="counter">${session.index+1}/${session.cards.length}</span></div><div class="prompt"><p class="eyebrow">${testing?'Recall the acronym and every point':'Learn the list'}</p><p class="topic ${testing&&!session.revealed?'topic-only':''}">${escapeHtml(c.topic)}</p>${testing?`<button class="acronym-peek ${session.revealed||session.acronymRevealed?'revealed':''}" data-acronym-reveal>${session.revealed||session.acronymRevealed?escapeHtml(c.acronym):'<span>Tap to reveal acronym</span>'}</button>`:`<div class="acronym">${escapeHtml(c.acronym)}</div>`}</div><div class="recall-card">${rows}</div>${c.review?'<div class="notice">Some wording in this source entry may need checking against the original notes.</div>':''}<div class="study-actions ${session.revealed?'ratings':''}">${session.mode==='learn'&&!session.revealed&&session.pointCount<c.points.length?'<button class="primary wide" data-next-point>Reveal next point</button>':!session.revealed?'<button class="primary wide" data-reveal>Reveal answer</button>':'<button class="rating" data-score="0">Missed</button><button class="rating" data-score="1">Nearly</button><button class="rating" data-score="2">Got it</button>'}</div>`;
}
function renderWeakPoint(){const x=session.cards[session.index];app.innerHTML=`<div class="study-head"><button class="back" data-exit>←</button><div class="study-progress"><i style="width:${(session.index/session.cards.length)*100}%"></i></div><span class="counter">${session.index+1}/${session.cards.length}</span></div><div class="prompt"><p class="eyebrow">Weak-point drill</p><p class="topic topic-only">${escapeHtml(x.card.topic)}</p><div class="acronym">${escapeHtml(x.card.acronym)} · ${x.point.letter}</div></div><div class="recall-card"><div class="point ${session.revealed?'':'concealed'}">${session.revealed?`<span class="letter">${x.point.letter}</span>`:''}<span class="point-text">${escapeHtml(x.point.text)}</span></div></div><div class="study-actions ${session.revealed?'ratings':''}">${session.revealed?'<button class="rating" data-point-drill="0">Missed</button><button class="rating" data-point-drill="1">Nearly</button><button class="rating" data-point-drill="2">Got it</button>':'<button class="primary wide" data-drill-reveal>Reveal point</button>'}</div>`}
function renderWrite(){const c=session.cards[session.index];if(session.writtenChecked)return app.innerHTML=`<div class="study-head"><button class="back" data-exit>←</button><div class="study-progress"><i style="width:${(session.index/session.cards.length)*100}%"></i></div><span class="counter">${session.index+1}/${session.cards.length}</span></div><div class="prompt"><p class="eyebrow">Compare your answer</p><p class="topic topic-only">${escapeHtml(c.topic)}</p><div class="acronym">${escapeHtml(c.acronym)}</div></div><div class="written-compare"><div><strong>Your answer</strong><p>${escapeHtml(session.writtenAnswer||'No answer entered').replace(/\n/g,'<br>')}</p></div><div><strong>Model answer</strong>${c.points.map(p=>`<p><b>${p.letter}</b> ${escapeHtml(p.text)}</p>`).join('')}</div></div><div class="study-actions ratings"><button class="rating" data-score="0">Missed</button><button class="rating" data-score="1">Nearly</button><button class="rating" data-score="2">Got it</button></div>`;app.innerHTML=`<div class="study-head"><button class="back" data-exit>←</button><div class="study-progress"><i style="width:${(session.index/session.cards.length)*100}%"></i></div><span class="counter">${session.index+1}/${session.cards.length}</span></div><div class="prompt"><p class="eyebrow">Write the whole list</p><p class="topic topic-only">${escapeHtml(c.topic)}</p></div><label class="field-label">Acronym<input id="writtenAcronym" class="search" autocomplete="off" placeholder="Type the mnemonic"></label><label class="field-label">Recall points<textarea id="writtenAnswer" class="written-input" rows="10" placeholder="Write one point per line"></textarea></label><button class="primary wide" data-check-written>Compare with answer</button>`}
function markPointReveal(card,index){const all=progress(),old=all[card.id]||{attempts:0,score:0,last:0,due:0},points=old.points||{},point=points[index]||{score:0,reveals:0};points[index]={score:Math.max(-5,(point.score||0)-1),reveals:(point.reveals||0)+1,last:Date.now()};all[card.id]={...old,points,due:0};save(all)}
function rate(score){const c=session.cards[session.index];const all=progress(),old=all[c.id]||{attempts:0,score:0},points=old.points||{};const gain=score===2?2:score===1?0.5:-1,quality=score===2&&!session.acronymRevealed?5:score===1?3:1;const next=Math.max(0,Math.min(8,(old.score||0)+(session.acronymRevealed?Math.min(0,gain):gain)));c.points.forEach((_,i)=>{if(session.revealedPoints.has(i))return;const point=points[i]||{score:0,reveals:0};points[i]={...reviewUpdate(point,score===2?5:score===1?3:1),score:Math.max(-5,Math.min(8,(point.score||0)+gain))}});all[c.id]={...old,...reviewUpdate(old,quality),attempts:(old.attempts||0)+1,score:next,points,acronymReveals:(old.acronymReveals||0)+(session.acronymRevealed?1:0)};save(all);session.results.push(score);session.index++;session.revealed=false;session.acronymRevealed=false;session.revealedPoints=new Set();session.pointCount=session.mode==='learn'?1:0;session.writtenChecked=false;renderStudy()}
function ratePoint(card,index,score){const all=progress(),old=all[card.id]||{attempts:0,score:0},points=old.points||{},point=points[index]||{score:0,reveals:0},gain=score===2?2:score===1?.5:-1;points[index]={...reviewUpdate(point,score===2?5:score===1?3:1),score:Math.max(-5,Math.min(8,(point.score||0)+gain)),rated:(point.rated||0)+1};all[card.id]={...old,points,due:score===2?old.due||Date.now()+86400000:0};save(all)}
function renderSummary(){const got=session.results.filter(x=>x===2).length;const nearly=session.results.filter(x=>x===1).length;const pct=Math.round(((got+nearly*.5)/(session.results.length||1))*100);app.innerHTML=`<div class="summary"><p class="eyebrow">Session complete</p><h1>Good retrieval<br>work.</h1><div class="summary-ring" style="--pct:${pct}%"><strong>${pct}%</strong></div><p class="muted">${got} recalled · ${nearly} nearly · ${session.results.length-got-nearly} missed</p><button class="primary wide" data-finish>Back to today</button></div>`}
function render(){app.innerHTML=view==='home'?home():view==='practice'?practice():view==='library'?library():progressView()}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.rowScore!==undefined){e.stopPropagation();ratePoint(session.cards[session.index],Number(b.dataset.index),Number(b.dataset.rowScore));b.parentElement.innerHTML='<em>Recorded</em>';return}if(b?.dataset.pointDrill!==undefined){const x=session.cards[session.index];ratePoint(x.card,x.index,Number(b.dataset.pointDrill));session.results.push(Number(b.dataset.pointDrill));session.index++;session.revealed=false;return renderStudy()}if(b?.dataset.drillReveal!==undefined){session.revealed=true;return renderStudy()}if(b?.dataset.checkWritten!==undefined){session.writtenAnswer=`${document.querySelector('#writtenAcronym').value}\n${document.querySelector('#writtenAnswer').value}`;session.writtenChecked=true;return renderStudy()}const acronym=e.target.closest('[data-acronym-reveal]');if(acronym&&session&&!session.revealed){session.acronymRevealed=true;return renderStudy()}const row=e.target.closest('[data-point]');if(row&&session&&!session.revealed){const index=Number(row.dataset.point);if(!session.revealedPoints.has(index))markPointReveal(session.cards[session.index],index);session.revealedPoints.add(index);return renderStudy()}if(!b)return;if(b.dataset.view)return setView(b.dataset.view);if(b.dataset.start)return start(b.dataset.start);if(b.dataset.reveal!==undefined){session.revealed=true;return renderStudy()}if(b.dataset.nextPoint!==undefined){session.pointCount++;return renderStudy()}if(b.dataset.score!==undefined)return rate(Number(b.dataset.score));if(b.dataset.exit!==undefined||b.dataset.finish!==undefined)return setView('home');if(b.dataset.card)return start('learn',cards.find(c=>c.id===b.dataset.card));if(b.dataset.category!==undefined){document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));filterLibrary()}if(b.id==='resetButton'&&confirm('Reset all saved practice progress on this device?')){localStorage.removeItem(STORE);render()}});
document.addEventListener('keydown',e=>{const row=e.target.closest?.('[data-point]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();row.click()}});
document.addEventListener('input',e=>{if(e.target.id==='search')filterLibrary();if(e.target.id==='examDate'){localStorage.setItem(SETTINGS,JSON.stringify({...settings(),examDate:e.target.value}));render()}});
function filterLibrary(){const q=(document.querySelector('#search')?.value||'').toLowerCase(),cat=document.querySelector('.filter.active')?.dataset.category||'All';const list=cards.filter(c=>(cat==='All'||c.category===cat)&&(`${c.acronym} ${c.topic} ${c.points.map(p=>p.text).join(' ')}`).toLowerCase().includes(q));document.querySelector('#libraryList').innerHTML=libraryRows(list)}

fetch('data.json?v=6').then(r=>r.json()).then(data=>{cards=data;render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js?v=6')}).catch(()=>{app.innerHTML='<div class="empty">The revision list could not be loaded. Please refresh and try again.</div>'});
